// OTHVM — Shopify Store Admin (Admin GraphQL API).
// Env: SHOPIFY_STORE_DOMAIN, SHOPIFY_ADMIN_TOKEN, optional SHOPIFY_API_VERSION.
// Required app scopes: read_products, write_products, read_orders, read_inventory, read_locations.
// Operations: shop | products | product | product_variants | orders | order | create_product | update_product | update_variant_price | raw

const input = $json || {};
const op = String(input.operation || 'shop').toLowerCase().trim();
const clean = (v) => String(v == null ? '' : v).trim();
const env = (k) => {
  try {
    return clean($env[k]);
  } catch (e) {
    return '';
  }
};
const http = (opts) => this.helpers.httpRequest(opts);
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, Number(n) || lo));

const DOMAIN = env('SHOPIFY_STORE_DOMAIN').replace(/^https?:\/\//i, '').replace(/\/.*$/, '');
const TOKEN = env('SHOPIFY_ADMIN_TOKEN');
const VERSION = env('SHOPIFY_API_VERSION') || '2026-07';
const SCOPES = ['read_products', 'write_products', 'read_orders', 'read_inventory', 'read_locations'];

if (!DOMAIN || !TOKEN) {
  return [
    {
      json: {
        ok: false,
        operation: op,
        error: 'Shopify is not configured. Set SHOPIFY_STORE_DOMAIN and SHOPIFY_ADMIN_TOKEN, then activate this workflow.',
        required_env: ['SHOPIFY_STORE_DOMAIN', 'SHOPIFY_ADMIN_TOKEN'],
        required_scopes: SCOPES,
      },
    },
  ];
}

const endpoint = 'https://' + DOMAIN + '/admin/api/' + VERSION + '/graphql.json';

async function gql(query, variables) {
  try {
    const r = await http({
      method: 'POST',
      url: endpoint,
      headers: { 'X-Shopify-Access-Token': TOKEN, 'Content-Type': 'application/json' },
      body: { query, variables: variables || {} },
      json: true,
      timeout: 30000,
    });
    if (r && Array.isArray(r.errors) && r.errors.length) {
      return { ok: false, error: r.errors.map((e) => e.message).join('; ') };
    }
    return { ok: true, data: (r && r.data) || null };
  } catch (e) {
    let msg = (e && e.message) || 'Shopify request failed';
    const b = e && e.response && e.response.body;
    if (b) {
      if (typeof b === 'string') msg = b;
      else msg = b.errors || b.error || b.message || JSON.stringify(b);
    }
    return { ok: false, error: String(msg).slice(0, 500) };
  }
}

const gid = (kind, value) => {
  const v = clean(value);
  if (!v) return '';
  return v.indexOf('gid://') === 0 ? v : 'gid://shopify/' + kind + '/' + v;
};

const strip = (o) => {
  const out = {};
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (v !== null && v !== undefined && v !== '') out[k] = v;
  }
  return out;
};

const mutationErrors = (data) => {
  if (!data) return [];
  for (const key of Object.keys(data)) {
    const v = data[key];
    if (v && Array.isArray(v.userErrors) && v.userErrors.length) {
      return v.userErrors.map((e) => (Array.isArray(e.field) ? e.field.join('.') + ': ' : '') + e.message);
    }
  }
  return [];
};

async function run() {
  if (op === 'shop') {
    return gql(
      'query ShopInfo { shop { name myshopifyDomain currencyCode email primaryDomain { url } plan { displayName } } }'
    );
  }

  if (op === 'products') {
    return gql(
      'query Products($first: Int!, $query: String) { products(first: $first, query: $query) { nodes { id title handle status vendor productType totalInventory updatedAt priceRangeV2 { minVariantPrice { amount currencyCode } maxVariantPrice { amount currencyCode } } } } }',
      { first: clamp(input.limit, 1, 100), query: clean(input.query) || null }
    );
  }

  if (op === 'product') {
    const id = gid('Product', input.product_id);
    if (!id) return { ok: false, error: 'product_id is required.' };
    return gql(
      'query Product($id: ID!) { product(id: $id) { id title handle status vendor productType descriptionHtml tags totalInventory updatedAt variants(first: 100) { nodes { id title sku price inventoryQuantity } } } }',
      { id }
    );
  }

  if (op === 'product_variants') {
    const id = gid('Product', input.product_id);
    if (!id) return { ok: false, error: 'product_id is required.' };
    return gql(
      'query ProductVariants($id: ID!) { product(id: $id) { id title variants(first: 100) { nodes { id title sku price inventoryQuantity } } } }',
      { id }
    );
  }

  if (op === 'orders') {
    return gql(
      'query Orders($first: Int!, $query: String) { orders(first: $first, query: $query, sortKey: CREATED_AT, reverse: true) { nodes { id name createdAt updatedAt displayFinancialStatus displayFulfillmentStatus totalPriceSet { shopMoney { amount currencyCode } } customer { displayName email } lineItems(first: 10) { nodes { title quantity } } } } }',
      { first: clamp(input.limit, 1, 100), query: clean(input.query) || null }
    );
  }

  if (op === 'order') {
    const id = gid('Order', input.order_id);
    if (!id) return { ok: false, error: 'order_id is required.' };
    return gql(
      'query Order($id: ID!) { order(id: $id) { id name createdAt displayFinancialStatus displayFulfillmentStatus note totalPriceSet { shopMoney { amount currencyCode } } customer { displayName email } lineItems(first: 50) { nodes { title quantity sku originalUnitPriceSet { shopMoney { amount currencyCode } } } } } }',
      { id }
    );
  }

  if (op === 'create_product') {
    const title = clean(input.title);
    if (!title) return { ok: false, error: 'title is required to create a product.' };
    const product = strip({
      title,
      descriptionHtml: clean(input.description),
      status: clean(input.status) || 'DRAFT',
      vendor: clean(input.vendor),
      productType: clean(input.product_type),
      tags: clean(input.tags)
        ? clean(input.tags)
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean)
        : null,
    });
    return gql(
      'mutation CreateProduct($input: ProductCreateInput!) { productCreate(product: $input) { product { id title handle status } userErrors { field message } } }',
      { input: product }
    );
  }

  if (op === 'update_product') {
    const id = gid('Product', input.product_id);
    if (!id) return { ok: false, error: 'product_id is required.' };
    const product = strip({
      id,
      title: clean(input.title),
      descriptionHtml: clean(input.description),
      status: clean(input.status),
      vendor: clean(input.vendor),
      productType: clean(input.product_type),
      tags: clean(input.tags)
        ? clean(input.tags)
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean)
        : null,
    });
    return gql(
      'mutation UpdateProduct($input: ProductUpdateInput!) { productUpdate(product: $input) { product { id title handle status updatedAt } userErrors { field message } } }',
      { input: product }
    );
  }

  if (op === 'update_variant_price') {
    const id = gid('ProductVariant', input.variant_id);
    const price = clean(input.price);
    if (!id || !price) return { ok: false, error: 'variant_id and price are required.' };
    return gql(
      'mutation UpdateVariantPrice($productVariant: ProductVariantInput!) { productVariantUpdate(productVariant: $productVariant) { productVariant { id title price } userErrors { field message } } }',
      { productVariant: { id, price } }
    );
  }

  if (op === 'raw') {
    const query = clean(input.query);
    if (!query) return { ok: false, error: 'query is required for raw.' };
    return gql(query, input.variables && typeof input.variables === 'object' ? input.variables : {});
  }

  return { ok: false, error: 'Unknown operation: ' + op };
}

const result = await run();
if (!result.ok) {
  return [{ json: { ok: false, operation: op, error: result.error, required_scopes: SCOPES } }];
}

const errors = mutationErrors(result.data);
if (errors.length) {
  return [{ json: { ok: false, operation: op, error: errors.join('; '), data: result.data, required_scopes: SCOPES } }];
}

return [{ json: { ok: true, operation: op, data: result.data } }];
